css:
body {
  margin: 0;
  font-family: Arial, sans-serif;
  background-color: #f0f0f0;
}

#game-container {
  display: flex;
  justify-content: center;
  align-items: center;
  height: 100vh;
  background-color: #ff4d4d;
}

#game-area {
  width: 80%;
  height: 80%;
  background-color: #800080;
  position: relative;
}

#update-menu {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-color: rgba(255, 255, 255, 0.9);
  display: flex;
  justify-content: center;
  align-items: center;
}

.hidden {
  display: none;
}

#update-content {
  background-color: #ff9999;
  padding: 20px;
  border-radius: 10px;
  text-align: center;
}

#resume-button {
  background-color: #b300b3;
  color: white;
  padding: 10px 20px;
  border: none;
  border-radius: 5px;
  cursor: pointer;
}

#resume-button:hover {
  background-color: #800080;
}

javascript:
var gamePaused = false;

function toggleUpdateMenu() {
  var updateMenu = document.getElementById('update-menu');
  if (gamePaused) {
    updateMenu.classList.add('hidden');
    gamePaused = false;
    resumeGame();
  } else {
    updateMenu.classList.remove('hidden');
    gamePaused = true;
    pauseGame();
  }
}

function pauseGame() {
  // Logic to pause the game
}

function resumeGame() {
  // Logic to resume the game
}

document.getElementById('resume-button').addEventListener('click', toggleUpdateMenu);

function sendDataToServer(data) {
  $.ajax({
    type: "POST",
    url: "/skibidi",
    data: JSON.stringify(data),
    contentType: "application/json",
    success: function(response) {
      console.log("Confirm and run initiated successfully:", response);
    },
    error: function(error) {
      console.error("Error initiating confirm and run:", error);
    }
  });
}

